const encoded: Readonly<Record<string, string>> = {
  "sn-mathphys-num.bst":
    "",
  "sn-jnl.cls":
    "",
};
export const assets: Readonly<Record<string, Uint8Array>> = Object.fromEntries(
  Object.entries(encoded).map(([name, value]) => [
    name,
    Uint8Array.from(atob(value), (character) => character.charCodeAt(0)),
  ]),
);
